import{_ as o,l as i,o as e,c as n,v as t,p as s,x as l,d,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"部署后监控","description":"","frontmatter":{"title":"部署后监控","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/deployment-monitoring.md","filePath":"llm/deployment-monitoring.md","lastUpdated":1789023840000}'),h={name:"llm/deployment-monitoring.md"};function c(_,a,E,A,f,B){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="部署后监控" tabindex="-1">部署后监控 <a class="header-anchor" href="#部署后监控" aria-label="Permalink to &quot;部署后监控&quot;">​</a></h1><div class="epigraph"><p>上线之后分布会变：用户、工具、对手、模型自己的级联。评测集停在发版日；监控必须在流量上继续抽样。</p><footer>—— 对照产品安全运营与模型漂移监测；政策框见 [RSP](/llm/safety-levels-rsp)</footer></div><p><a href="/llm/safety-levels-rsp">上一课</a>把门槛写在发版前。本课是补层「对齐理论与失效」的收束：部署后监控——在真实流量上抽检滥用、越狱、幻觉、提取迹象与能力漂移。缺口不是再做一次 Arena，而是承认发版评测的支持与线上支持不同。下一课程检索与嵌入不再默认「对齐已经结束」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>发版用固定提示集。线上会出现新工具、新越狱文风、新的级联代理、新的版权投诉。若只靠内容过滤器的精确率，会漏掉 <a href="/llm/indirect-injection">间接注入</a> 与缓慢的奖励黑客（用户用产品指标当 RM）。缺口是闭环：抽样、标注或分类器、升级、是否触发 RSP 再评测。</p><p><span class="marginnote">监控可以是隐私敏感的。设计应默认最小化内容留存、聚合优先、人工抽检有权限边界。本课不写如何大规模存储用户对话。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小闭环：风险分层抽样（工具调用、长上下文、新用户、高权限连接加权）；自动分类器只做分流，人类看边界；仪表：越狱命中、拒答漂移、提取性重复查询、水印检测、<a href="/llm/hallucination-taxonomy">幻觉</a> 分列投诉。发现能力带可疑上升：回到危险能力评测，而不是只加一条过滤规则。发现提取：结合指纹与风控，而不是公开对质细节。</p>',8)),(e(),s(p,null,{default:l(()=>[m(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRAF%5B%22%E7%BA%BF%E4%B8%8A%E6%B5%81%E9%87%8F%22%5D%20--%3E%20SAMP%5B%22%E5%88%86%E5%B1%82%E6%8A%BD%E6%A0%B7%22%5D%0A%20%20SAMP%20--%3E%20CLS%5B%22%E5%88%86%E7%B1%BB%20%2F%20%E4%BA%BA%E5%AE%A1%22%5D%0A%20%20CLS%20--%3E%20FIX%5B%22%E8%BF%87%E6%BB%A4%E5%99%A8%20%2F%20%E7%AD%96%E7%95%A5%22%5D%0A%20%20CLS%20--%3E%20RE%5B%22%E8%A7%A6%E5%8F%91%E5%86%8D%E8%AF%84%E6%B5%8B%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分布漂移使发版 RM 与安全分类器过时，与训练期 <a href="/llm/reward-hacking-llm">过优化</a> 同构，只是优化器换成了用户与对手。监控的统计对象是<strong>速率与分位</strong>，不是单条奇闻。没有持有标注流，分类器会自己漂移——需要定期校准集。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供监控用户的隐蔽手段，不提供绕过产品安全的流量特征。对齐补层在此结束；检索课从嵌入训练另起，默认你已知道：上线后 \\(R^*\\) 仍要被测量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>部署后监控补发版评测的分布缺口。</li><li>闭环：抽样 → 分流 → 修复或再评测。</li><li>能力带可疑上升走 RSP，不只加过滤器。</li><li>出处：RSP 课；线上安全运营常识；奖励黑客与注入课。</li></ul>',6))])}const P=o(h,[["render",c]]);export{S as __pageData,P as default};
